    antienne_ouverture: [
        {class:"indent1all", texte: `Dans son Église, le Seigneur lui a donné la parole ;`},
        {class:"indent1all", texte: `il l’a rempli de l’esprit de sagesse et d’intelligence, et l’a revêtu de gloire.`}],
